using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using UnscRelay.Core;
internal static class ItemDiscussionChecks
{
 public static int Run(){var count=0;void Check(bool good,string label){if(!good)throw new Exception(label);count++;Console.WriteLine("PASS discussion: "+label);}void Reject(Action test,string label){try{test();}catch(ArgumentException){Check(true,label);return;}throw new Exception(label);}
 var now=DateTimeOffset.Parse("2026-11-18T12:00:00Z");var comments=ItemDiscussion.Append(null," Author "," <script>fixture()</script> ",now);Check(comments[0].Author=="Author"&&comments[0].Text=="<script>fixture()</script>","plain text and trimmed labels are preserved");var next=ItemDiscussion.Append(comments,"Other author","Reply",now);Check(next.Count==2&&comments.Count==1,"append does not mutate prior messages");Reject(()=>ItemDiscussion.Validate([comments[0],comments[0]]),"duplicate comment ids are refused");Reject(()=>ItemDiscussion.Append(comments,"Author",new string('x',4001),now),"oversized text is refused");Reject(()=>ItemDiscussion.Append(comments,"Author\0", "Text",now),"control characters are refused");Reject(()=>ItemDiscussion.Append(comments,"Author","Text",now.AddYears(100)),"unsupported dates are refused");Reject(()=>ItemDiscussion.Validate(Enumerable.Range(0,101).Select(index=>comments[0] with{Id=Guid.NewGuid().ToString("D")}).ToList()),"discussion size is bounded");
 var info=new KeyInfo("discussion-fixture","Fixture","",now.UtcDateTime,Kind:"password",Discussion:comments);using var doc=JsonDocument.Parse(JsonSerializer.SerializeToUtf8Bytes(new[]{new{info,content=Convert.ToBase64String(Encoding.UTF8.GetBytes("fixture"))}},VaultSyncCrypto.Json));var snapshot=new PortableSnapshot(2,doc.RootElement,new AppData(),[]);var bytes=JsonSerializer.SerializeToUtf8Bytes(snapshot,VaultSyncCrypto.Json);var parsed=VaultSyncCrypto.Parse(bytes);Check(parsed.Records[0].GetProperty("info").GetProperty("discussion")[0].GetProperty("text").GetString()==comments[0].Text,"strict portable schema preserves discussion metadata");var key=RandomNumberGenerator.GetBytes(32);try{var envelope=VaultSyncCrypto.Create(new string('A',64),"Fixture recovery code 2026!",key,bytes);Check(!JsonSerializer.Serialize(envelope).Contains("fixture()</script>"),"server envelope contains no plaintext conversation");var opened=VaultSyncCrypto.Open(envelope,envelope.Owner,key);try{Check(VaultSyncCrypto.Canonicalize(opened).SequenceEqual(VaultSyncCrypto.Canonicalize(bytes)),"encrypted round trip preserves discussion");}finally{CryptographicOperations.ZeroMemory(opened);}}finally{CryptographicOperations.ZeroMemory(key);CryptographicOperations.ZeroMemory(bytes);}Console.WriteLine("Item discussion checks: "+count);return 0;}
}
